INSERT INTO `translations` (`language`, `key`, `value`) VALUES
  ('en', 'common.protected_notice.title', 'Protected by RockGuide'),
  ('es', 'common.protected_notice.title', 'Protección RockGuide'),
  ('fr', 'common.protected_notice.title', 'Protection RockGuide'),
  ('de', 'common.protected_notice.title', 'RockGuide-Schutz'),
  ('zh', 'common.protected_notice.title', 'RockGuide 保障'),
  ('it', 'common.protected_notice.title', 'Protezione RockGuide'),
  ('ja', 'common.protected_notice.title', 'RockGuide の保護'),
  ('ru', 'common.protected_notice.title', 'Защита RockGuide'),
  ('ko', 'common.protected_notice.title', 'RockGuide 보호'),
  ('ar', 'common.protected_notice.title', 'حماية RockGuide'),
  ('tr', 'common.protected_notice.title', 'RockGuide Koruması'),
  ('pt', 'common.protected_notice.title', 'Proteção RockGuide'),
  ('el', 'common.protected_notice.title', 'Προστασία RockGuide'),
  ('th', 'common.protected_notice.title', 'การคุ้มครองของ RockGuide'),
  ('uk', 'common.protected_notice.title', 'Захист RockGuide'),
  ('en', 'common.protected_notice.body_fee', 'Paying here means you’re refunded by the rules shown — in full if the guide declines, doesn’t answer or cancels — and we can help if something goes wrong. Payments made outside RockGuide aren’t covered.'),
  ('es', 'common.protected_notice.body_fee', 'Pagar aquí significa que se te reembolsa según las reglas mostradas (todo si el guía rechaza, no responde o cancela) y que podemos ayudarte si algo sale mal. Los pagos fuera de RockGuide no están cubiertos.'),
  ('fr', 'common.protected_notice.body_fee', 'Payer ici, c’est être remboursé selon les règles affichées — intégralement si le guide refuse, ne répond pas ou annule — et pouvoir compter sur notre aide en cas de problème. Les paiements hors RockGuide ne sont pas couverts.'),
  ('de', 'common.protected_notice.body_fee', 'Wenn du hier zahlst, wirst du nach den angezeigten Regeln erstattet – voll, wenn der Guide ablehnt, nicht antwortet oder storniert – und wir helfen, wenn etwas schiefgeht. Zahlungen außerhalb von RockGuide sind nicht abgedeckt.'),
  ('zh', 'common.protected_notice.body_fee', '在这里付款，即可按所示规则退款——导游拒绝、未回复或取消时全额退款——出现问题时我们也能提供帮助。在 RockGuide 之外的付款不受保障。'),
  ('it', 'common.protected_notice.body_fee', 'Pagando qui vieni rimborsato secondo le regole indicate — per intero se la guida rifiuta, non risponde o annulla — e possiamo aiutarti se qualcosa va storto. I pagamenti fuori da RockGuide non sono coperti.'),
  ('ja', 'common.protected_notice.body_fee', 'ここで支払えば、表示のルールどおりに返金されます（ガイドが断る・返答しない・キャンセルした場合は全額）。問題が起きたときもサポートします。RockGuide の外での支払いは対象外です。'),
  ('ru', 'common.protected_notice.body_fee', 'Оплата здесь означает возврат по указанным правилам — полный, если гид откажет, не ответит или отменит, — и нашу помощь, если что-то пойдёт не так. Оплата вне RockGuide не защищена.'),
  ('ko', 'common.protected_notice.body_fee', '여기서 결제하면 안내된 규칙에 따라 환불받을 수 있으며(가이드가 거절·무응답·취소하면 전액), 문제가 생기면 도와드립니다. RockGuide 밖에서 한 결제는 보호되지 않습니다.'),
  ('ar', 'common.protected_notice.body_fee', 'الدفع هنا يعني استرداد المبلغ وفق القواعد المعروضة — كاملًا إذا رفض المرشد أو لم يرد أو ألغى — وأننا نستطيع المساعدة إذا حدثت مشكلة. المدفوعات خارج RockGuide غير مشمولة.'),
  ('tr', 'common.protected_notice.body_fee', 'Burada ödemek, gösterilen kurallara göre iade almanız demektir — rehber reddeder, yanıt vermez veya iptal ederse tamamı — ve bir sorun olursa yardımcı olabiliriz. RockGuide dışındaki ödemeler kapsam dışıdır.'),
  ('pt', 'common.protected_notice.body_fee', 'Pagar aqui significa ser reembolsado pelas regras indicadas — na totalidade se o guia recusar, não responder ou cancelar — e poder contar com a nossa ajuda se algo correr mal. Pagamentos fora do RockGuide não estão cobertos.'),
  ('el', 'common.protected_notice.body_fee', 'Πληρώνοντας εδώ παίρνετε επιστροφή σύμφωνα με τους κανόνες — ολόκληρη αν ο ξεναγός αρνηθεί, δεν απαντήσει ή ακυρώσει — και μπορούμε να βοηθήσουμε αν κάτι πάει στραβά. Οι πληρωμές εκτός RockGuide δεν καλύπτονται.'),
  ('th', 'common.protected_notice.body_fee', 'การจ่ายที่นี่หมายถึงคุณได้รับเงินคืนตามกฎที่แสดง — เต็มจำนวนหากไกด์ปฏิเสธ ไม่ตอบ หรือยกเลิก — และเราช่วยได้หากเกิดปัญหา การจ่ายเงินนอก RockGuide ไม่ได้รับการคุ้มครอง'),
  ('uk', 'common.protected_notice.body_fee', 'Оплата тут означає повернення коштів за вказаними правилами — повне, якщо гід відмовить, не відповість чи скасує, — і нашу допомогу, якщо щось піде не так. Оплата поза RockGuide не захищена.'),
  ('en', 'common.protected_notice.body_pack', 'Picks are used only when you choose a guide, and a pick comes back if a match you booked is cancelled. Book and pay guides here too: trips arranged outside RockGuide aren’t covered.'),
  ('es', 'common.protected_notice.body_pack', 'Las selecciones solo se gastan cuando eliges un guía, y recuperas una si se cancela un viaje reservado. Reserva y paga a los guías también aquí: los viajes acordados fuera de RockGuide no están cubiertos.'),
  ('fr', 'common.protected_notice.body_pack', 'Les choix ne sont utilisés que lorsque vous choisissez un guide, et un choix vous est rendu si un voyage réservé est annulé. Réservez et payez aussi les guides ici : les voyages organisés hors RockGuide ne sont pas couverts.'),
  ('de', 'common.protected_notice.body_pack', 'Picks werden nur verbraucht, wenn du einen Guide auswählst, und du bekommst einen zurück, wenn eine gebuchte Tour storniert wird. Buche und bezahle Guides auch hier: Touren außerhalb von RockGuide sind nicht abgedeckt.'),
  ('zh', 'common.protected_notice.body_pack', '只有在你选择导游时才会用掉选择次数，已预订的行程被取消时会退还。也请在这里预订并付款给导游：在 RockGuide 之外安排的行程不受保障。'),
  ('it', 'common.protected_notice.body_pack', 'Le scelte si usano solo quando scegli una guida, e ne recuperi una se un viaggio prenotato viene annullato. Prenota e paga le guide anche qui: i viaggi organizzati fuori da RockGuide non sono coperti.'),
  ('ja', 'common.protected_notice.body_pack', '選択枠はガイドを選んだときだけ使われ、予約したツアーがキャンセルされると戻ります。ガイドの予約と支払いもここで：RockGuide の外で手配したツアーは対象外です。'),
  ('ru', 'common.protected_notice.body_pack', 'Выборы тратятся, только когда вы выбираете гида, и возвращаются, если забронированная поездка отменена. Бронируйте и оплачивайте гидов тоже здесь: поездки вне RockGuide не защищены.'),
  ('ko', 'common.protected_notice.body_pack', '선택권은 가이드를 고를 때만 사용되며, 예약한 여행이 취소되면 돌려받습니다. 가이드 예약과 결제도 여기서 하세요. RockGuide 밖에서 정한 여행은 보호되지 않습니다.'),
  ('ar', 'common.protected_notice.body_pack', 'لا تُستخدم الاختيارات إلا عند اختيار مرشد، ويُعاد الاختيار إذا أُلغيت رحلة محجوزة. احجز وادفع للمرشدين هنا أيضًا: الرحلات المرتّبة خارج RockGuide غير مشمولة.'),
  ('tr', 'common.protected_notice.body_pack', 'Seçimler yalnızca bir rehber seçtiğinizde kullanılır ve rezerve edilen bir tur iptal edilirse geri verilir. Rehberleri de burada rezerve edip ödeyin: RockGuide dışında ayarlanan turlar kapsam dışıdır.'),
  ('pt', 'common.protected_notice.body_pack', 'As escolhas só são usadas quando escolhe um guia, e recupera uma se uma viagem reservada for cancelada. Reserve e pague aos guias também aqui: viagens combinadas fora do RockGuide não estão cobertas.'),
  ('el', 'common.protected_notice.body_pack', 'Οι επιλογές χρησιμοποιούνται μόνο όταν επιλέγετε ξεναγό και επιστρέφεται μία αν ακυρωθεί κρατημένο ταξίδι. Κλείστε και πληρώστε ξεναγούς επίσης εδώ: ταξίδια εκτός RockGuide δεν καλύπτονται.'),
  ('th', 'common.protected_notice.body_pack', 'สิทธิ์เลือกจะถูกใช้เมื่อคุณเลือกไกด์เท่านั้น และจะได้คืนหากทริปที่จองถูกยกเลิก จองและจ่ายเงินให้ไกด์ที่นี่ด้วย: ทริปที่จัดนอก RockGuide ไม่ได้รับการคุ้มครอง'),
  ('uk', 'common.protected_notice.body_pack', 'Вибори витрачаються лише тоді, коли ви обираєте гіда, і повертаються, якщо заброньовану поїздку скасовано. Бронюйте й оплачуйте гідів теж тут: поїздки поза RockGuide не захищені.'),
